// de.yaml def lowerWords
export function lowerWords(text: string) {
  return (text.match(/\p{L}+/gu) ?? []).map((w) => w.toLowerCase());
}

// de.yaml def clauseRest
export function clauseRest(ctx: DetectContext, m: RegExpExecArray) {
  return ctx.text.slice(m.index + m[0].length, m.index + m[0].length + 120).split(/[.!?;,:\n]/)[0];
}

// de.yaml def clauseBefore
export function clauseBefore(ctx: DetectContext, m: RegExpExecArray) {
  return (
    ctx.text
      .slice(Math.max(0, m.index - 120), m.index)
      .split(/[.!?;,:\n]/)
      .at(-1) ?? ""
  );
}

// de.yaml def idiomGroup
export function idiomGroup(m: RegExpExecArray) {
  return ["target", "t2", "t3", "t4", "t5"].find((k) => m.groups![k] !== undefined)!;
}

// de.yaml def idiomOpen
export function idiomOpen(m: RegExpExecArray, ctx: DetectContext) {
  const name = idiomGroup(m);
  return (
    !ctx.dictionary.has(m.groups![name].toLowerCase()) &&
    !namedExampleBefore(ctx.text, m.indices!.groups![name][0])
  );
}

// de.yaml def idiomFinding
export function idiomFinding(
  m: RegExpExecArray,
  ctx: DetectContext,
  frame: FrameRef,
  fixed: string | readonly string[],
) {
  const name = idiomGroup(m);
  const span = m.indices!.groups![name];
  const typed = m.groups![name];
  const replacements = [fixed].flat().filter((r) => r !== typed);
  if (!(replacements.length > 0)) return null;
  return remember(IDIOM_FINDINGS, {
    ruleId: "germanNounCasing",
    messageKey: frame.messageKey,
    range: { start: span[0], end: span[1] },
    alternatives: replacements,
    ...(replacements.length > 1 ? { requiresChoice: true as const } : {}),
    context: { start: Math.max(0, span[0] - 40), end: Math.min(ctx.text.length, span[1] + 40) },
  });
}

// de.yaml def ordinalAsNoun
export function ordinalAsNoun(m: RegExpExecArray, ctx: DetectContext) {
  const article = /(\p{L}+)[ \t]+$/u.exec(m.input.slice(Math.max(0, m.index - 8), m.index))?.[1];
  const next =
    /^,[ \t]+\p{L}+[ \t]+(\p{L}+)/u.exec(m.input.slice(m.index + m[0].length))?.[1] ?? "";
  if (!(article?.toLowerCase() === m.groups!.relative && !/^\p{Ll}+e[nmrs]?$/u.test(next)))
    return false;
  const sentence = ctx.text
    .slice(Math.max(0, m.index - 120), m.index)
    .split(/[.!?\n]/)
    .at(-1)!;
  return !/[ \t]\p{Lu}/u.test(sentence);
}

// de.yaml def politeOpens
export function politeOpens(token: string | undefined) {
  return token === undefined || /^(?:[.!?:,;„“"»«]|\n)$/.test(token);
}

// de.yaml def BOUNDARY
export const BOUNDARY = /^(?:[.!?:;,()"“”„«»–—\n-]|$)/;

// de.yaml rule de.dates def WEEKDAYS
export const WEEKDAYS = [
  "Sonntag",
  "Montag",
  "Dienstag",
  "Mittwoch",
  "Donnerstag",
  "Freitag",
  "Samstag",
];

